# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Look up a character's stock icon (64x64 PNG in pkgs/ds/data/char_icons/, downloaded
#          by `ds data char_icon`, see ds.data.raw.smashmate).
# Usage: `ds.data.char_icon_path("little_mac")` -> Path to little_mac.png
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from functools import cache
from pathlib import Path

import polars as pl

from ds.data.raw.smashmate import SHARED_FILE, char_icon_file

__all__ = ["CHAR_ICON_DIR", "char_icon", "char_icon_by_name", "char_icon_path"]

CHAR_ICON_DIR = Path(__file__).resolve().parent / "char_icons"
# Display names other sites use for an icon several of our char ids share -> its file's stem
_SHARED_NAMES = {"pokemon trainer": "ptrainer", "pyra mythra": "eflame", "aegis": "eflame"}


def _name_key(name: str) -> str:
    """A display name reduced for matching: 'Mr. Game & Watch' -> 'mr game watch'."""
    text = name.lower().replace("é", "e").replace("&", " ").replace("/", " ")
    words = re.sub(r"[^a-z0-9 ]", "", text.replace("-", " ").replace(".", " ")).split()
    return " ".join(word for word in words if word != "and")


@cache
def _icons_by_name() -> dict[str, str]:
    chars = pl.read_parquet(CHAR_ICON_DIR.parent / "char.parquet")
    by_name = {_name_key(name): char_icon for name, char_icon in chars.select("name", "char_icon").iter_rows()}
    by_name |= {
        _name_key(char_id): by_name[_name_key(name)] for char_id, name in chars.select("id", "name").iter_rows()
    }
    by_name |= {name: f"{CHAR_ICON_DIR.name}/{SHARED_FILE[site]}.png" for name, site in _SHARED_NAMES.items()}
    return by_name


def char_icon_by_name(name: str) -> str | None:
    """The icon for a character's display name as another site writes it (eg supermajor.gg's
    'Pac-Man', 'Pokemon Trainer', 'Pyra/Mythra'), as char.parquet's `char_icon` value; None if
    no character matches. Punctuation, case, '&' / 'and' don't matter; a char id works too.
    """
    return _icons_by_name().get(_name_key(name))


def char_icon(char_id: str) -> str:
    """The icon's path relative to pkgs/ds/data/, as in char.parquet's `char_icon` column,
    eg 'char_icons/little_mac.png'. Raises ValueError for an unknown char id.
    """
    return f"{CHAR_ICON_DIR.name}/{char_icon_file(char_id)}"


def char_icon_path(char_id: str) -> Path:
    """The icon file for a char id (char.parquet's `id`), eg .../char_icons/little_mac.png.

    The three Pokemon share Pokemon Trainer's icon, and Pyra and Mythra share one.
    Raises ValueError for an unknown char id.
    """
    return CHAR_ICON_DIR / char_icon_file(char_id)
